import {useWorkbenchRefresh} from './refresh.tsx';
import React,{useState} from 'react';
import {useResource} from './state.js';
import {useWritingRequest} from './writing-request.js';
import {useDialog} from '../dialog.tsx';
const style=`.cuigengji .relationship-type-picker{display:grid;gap:8px;min-width:0;grid-column:1/-1}.cuigengji .relationship-type-row{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.cuigengji .relationship-type-row>label:first-child{flex:1;min-width:140px}.cuigengji .relationship-type-row label{display:grid;gap:4px}.cuigengji .relationship-type-row select,.cuigengji .relationship-type-row input:not([type=color]){width:100%;min-width:0;max-width:100%;box-sizing:border-box}.cuigengji .relationship-type-row input[type=color]{width:44px;height:36px;padding:3px}.cuigengji .relationship-type-row button{min-height:36px}.cuigengji .relationship-type-editor{padding:10px;border:1px solid var(--line,#d8dee8);border-radius:8px;display:grid;gap:8px}.cuigengji .relationship-type-picker small{font-size:12px;opacity:.75}`;
export function RelationshipTypePicker({call,novelId,value,onChange,busy=false}){
 const {refresh}=useWorkbenchRefresh();
 const [poll,setPoll]=useState(0),[editing,setEditing]=useState(null),[saving,setSaving]=useState(false),[error,setError]=useState('');
 const resource=useResource(()=>call('writing.relationshipType.list',{novelId}),[call,novelId,poll],`${novelId}:relationship-types`),types=resource.value||[],selected=types.find(t=>t.id===value),write=useWritingRequest(call),{confirm}=useDialog();
 const save=async()=>{if(saving||!editing?.name.trim())return;setSaving(true);setError('');try{const result=await write(`writing.relationshipType.${editing.id?'update':'create'}`,{novelId,id:editing.id,expectedRevision:editing.revision||0,name:editing.name.trim(),color:editing.color});onChange(result.id,result);setEditing(null);setPoll(n=>n+1);refresh();}catch(e){setError(e.message);}finally{setSaving(false);}};
 const remove=async()=>{if(!selected||!await confirm('删除这个未使用的关系字段？已被连线或历史引用的字段不会删除。'))return;setSaving(true);setError('');try{await write('writing.relationshipType.delete',{novelId,id:selected.id,expectedRevision:selected.revision,confirmed:true});onChange(null);setEditing(null);setPoll(n=>n+1);refresh();}catch(e){setError(e.message);}finally{setSaving(false);}};
 return <section className="relationship-type-picker" aria-label="自定义关系字段"><style>{style}</style><div className="relationship-type-row"><label>关系字段<select aria-label="关系字段" disabled={busy||saving} value={value||''} onChange={e=>{const next=types.find(t=>t.id===e.target.value);onChange(next?.id||null,next);setEditing(null);setError('');}}><option value="">不使用字段（显示原名称）</option>{value&&!selected&&<option value={value}>正在读取关系字段…</option>}{types.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></label>{selected&&<span title={selected.color} aria-label={`字段颜色 ${selected.color}`} style={{background:selected.color,width:18,height:18,borderRadius:4,alignSelf:'center'}}/>}<button type="button" disabled={busy||saving} onClick={()=>{setError('');setEditing({name:'',color:'#ed9236'});}}>＋ 新建</button>{selected&&<button type="button" disabled={busy||saving} onClick={()=>{setError('');setEditing({...selected});}}>编辑字段</button>}</div>{editing&&<div className="relationship-type-editor"><div className="relationship-type-row"><label>字段名称<input aria-label="关系字段名称" maxLength={80} value={editing.name} onChange={e=>setEditing({...editing,name:e.target.value})} placeholder="例如：朋友"/></label><label>连线颜色<input aria-label="关系字段颜色" type="color" value={editing.color} onChange={e=>setEditing({...editing,color:e.target.value})}/></label></div><small>字段在本书内共用；修改名称或颜色会更新使用它的关系显示。</small><div className="relationship-type-row"><button type="button" disabled={busy||saving||!editing.name.trim()} onClick={save}>{saving?'保存中…':'保存字段'}</button><button type="button" disabled={saving} onClick={()=>setEditing(null)}>取消</button>{editing.id&&<button type="button" disabled={busy||saving} onClick={remove}>删除未使用字段</button>}</div></div>}{(error||resource.error)&&<p role="alert">{error||resource.error}</p>}</section>;
}
